<?php $pageTitle='Compras'; require_once __DIR__.'/../../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$fornecedor=(int)$_POST['fornecedor_id'];$produto=(int)$_POST['produto_id'];$qtd=(float)$_POST['quantidade'];$st=$pdo->prepare('SELECT * FROM produtos WHERE id=?');$st->execute([$produto]);$p=$st->fetch();$unit=(float)($_POST['preco_unitario']?:$p['preco_custo']);$total=$qtd*$unit;$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO compras(fornecedor_id,usuario_id,total,status) VALUES(?,?,?,"RECEBIDA")')->execute([$fornecedor,$_SESSION['user']['id'],$total]);$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO compra_itens(compra_id,produto_id,quantidade,preco_unitario,subtotal) VALUES(?,?,?,?,?)')->execute([$id,$produto,$qtd,$unit,$total]);$pdo->prepare('UPDATE produtos SET estoque_atual=estoque_atual+?,preco_custo=? WHERE id=?')->execute([$qtd,$unit,$produto]);$pdo->prepare('INSERT INTO movimentacoes_estoque(produto_id,tipo,quantidade,observacao,usuario_id) VALUES(?,?,?,?,?)')->execute([$produto,'ENTRADA',$qtd,'Compra #'.$id,$_SESSION['user']['id']]);$pdo->prepare('INSERT INTO financeiro(tipo,descricao,valor,vencimento,status,categoria) VALUES("DESPESA",?,?,CURDATE(),"PENDENTE","COMPRAS")')->execute(['Compra #'.$id,$total]);$pdo->commit();flash('ok','Compra recebida e estoque atualizado.');}catch(Throwable $e){$pdo->rollBack();flash('err',$e->getMessage());}header('Location:index.php');exit;}
$fornecedores=$pdo->query('SELECT id,razao_social FROM fornecedores WHERE status="ATIVO" ORDER BY razao_social')->fetchAll();$produtos=$pdo->query('SELECT id,sku,nome,preco_custo FROM produtos WHERE status="ATIVO" ORDER BY nome')->fetchAll();$rows=$pdo->query('SELECT c.*,f.razao_social fornecedor FROM compras c LEFT JOIN fornecedores f ON f.id=c.fornecedor_id ORDER BY c.id DESC')->fetchAll(); ?>
<div class="panel mb-3"><div class="panel-title"><h3>Registrar compra</h3></div><form method="post" class="row g-3"><div class="col-md-3"><label>Fornecedor</label><select name="fornecedor_id" class="form-select" required><?php foreach($fornecedores as $f):?><option value="<?=$f['id']?>"><?=e($f['razao_social'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Produto</label><select name="produto_id" class="form-select" required><?php foreach($produtos as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' - '.$p['nome'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Quantidade</label><input name="quantidade" type="number" step="0.01" class="form-control" required></div><div class="col-md-3"><label>Custo unitário</label><input name="preco_unitario" type="number" step="0.01" class="form-control" required></div><div class="col-12"><button class="btn btn-dark">Receber compra</button></div></form></div>
<div class="panel"><table class="table"><thead><tr><th>#</th><th>Data</th><th>Fornecedor</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=date('d/m/Y H:i',strtotime($r['data_compra']))?></td><td><?=e($r['fornecedor'])?></td><td><?=e($r['status'])?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>